pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, uint256 _blockTimestamp, uint256 _blockNumber) public {
        // Constrain to realistic values: _value around 10 ether, timestamp in valid range
        vm.assume(_value == 10 ether);
        vm.assume(_blockTimestamp >= 1 && _blockTimestamp <= type(uint40).max);
        vm.assume(_blockNumber >= 1);

        // Mine to a block number that is NOT a multiple of 15 to avoid balance transfer in reference
        vm.roll(_blockNumber - (_blockNumber % 15 == 0 ? 1 : 0));
        // Warp to a timestamp that will make the require pass in reference (strictly greater than pastBlockTime)
        vm.warp(_blockTimestamp);

        // Fund contract with initial balance
        uint256 initialBalance = 100 ether;
        vm.deal(address(c), initialBalance);

        // First call to set pastBlockTime
        (bool ok1,) = address(c).call{value: 10 ether}("");
        vm.assume(ok1);

        uint256 balanceAfterFirst = address(c).balance;
        uint256 pastBlockTimeAfterFirst = c.pastBlockTime();

        // Now try a call at the SAME timestamp (this should fail in reference, pass in mutant)
        vm.warp(pastBlockTimeAfterFirst); // exactly the same timestamp
        // Mine to a block that is NOT multiple of 15
        uint256 currentBlock = block.number;
        vm.roll(currentBlock + (15 - (currentBlock % 15))); // next multiple of 15

        // Make the call
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // The general rule: if the call succeeds, balance must remain unchanged (since block%15==0 and transfer happens)
        // Actually let's think: the invariant is that if block.timestamp == pastBlockTime, call should revert.
        // So we assert that ok2 is false (revert)
        assertTrue(!ok2, "Call with same timestamp should revert");
    }
}

