        vm.assume(value1 == 10 ether);
        vm.assume(value2 == 10 ether);

        // Ensure timestamp increases for first call (needed by reference)
        vm.warp(1000);

        // First call - must succeed
        (bool success1,) = address(c).call{value: value1}("");
        // Store timestamp after first call
        uint256 timeAfterFirst = block.timestamp;

        // Second call at same timestamp (or higher)
