        // General rule: If both calls succeeded and balance increased (no drain), 
        // then the timestamp must have strictly increased
        require(success1, "First call must succeed");
        if (success2) {
            // If second call succeeds, there are two cases:
            // 1. timestamp strictly increased -> contract may drain on next 15-block multiple
            // 2. timestamp equal -> contract cannot drain properly (mutant bug)
            // The invariant: balance can only stay same or decrease, never increase
            assertTrue(balanceAfter <= balanceBefore + value2, "Balance must not increase beyond the sent amount");
        }
    }
}

