import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNum1, uint256 blockNum2, uint256 balance) public {
        // Bound timestamps to avoid overflow, ensure timestamp2 >= timestamp1 for monotonicity
        vm.assume(timestamp1 >= 1 && timestamp2 >= timestamp1 && timestamp2 <= type(uint256).max - 10);
        // Bound block numbers to avoid issues, ensure blockNum2 >= blockNum1
        vm.assume(blockNum1 >= 1 && blockNum2 >= blockNum1 && blockNum2 <= type(uint256).max - 15);
        // Set initial balance
        vm.deal(address(c), balance);

        // First call: set pastBlockTime by sending exactly 10 ether
        vm.warp(timestamp1);
        vm.roll(blockNum1);
        uint256 balanceBefore = address(c).balance;
        (bool success1, ) = address(c).call{value: 10 ether}("");
        uint256 balanceAfter1 = address(c).balance;

        if (success1 && timestamp1 > c.pastBlockTime()) {
            // Successful call: balance increased by 10 ether, unless block.number % 15 == 0 (then it drains)
            if (blockNum1 % 15 == 0) {
                assertTrue(balanceAfter1 == 0, "Expected balance to drain on block multiple of 15");
            } else {
                assertTrue(balanceAfter1 == balanceBefore + 10 ether, "Expected balance increase by 10 ether");
            }
        } else {
            // Failed call: balance unchanged
            assertTrue(balanceAfter1 == balanceBefore, "Expected balance unchanged on failed call");
        }

        // Second call: ensure timestamps strictly increase for reference to behave as expected
        uint256 prevPastBlockTime = c.pastBlockTime();
        vm.warp(timestamp2);
        vm.roll(blockNum2);
        balanceBefore = address(c).balance;
        (bool success2, ) = address(c).call{value: 10 ether}("");
        uint256 balanceAfter2 = address(c).balance;

        if (success2 && timestamp2 > prevPastBlockTime) {
            if (blockNum2 % 15 == 0) {
                assertTrue(balanceAfter2 == 0, "Expected balance to drain on block multiple of 15");
            } else {
                assertTrue(balanceAfter2 == balanceBefore + 10 ether, "Expected balance increase by 10 ether");
            }
        } else {
            assertTrue(balanceAfter2 == balanceBefore, "Expected balance unchanged on failed call");
        }
    }
