pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNum1, uint256 blockNum2, uint256 amount) public {
        // Restrict timestamps to be plausible
        vm.assume(timestamp1 >= 1);
        vm.assume(timestamp2 >= 1);
        // Ensure block numbers are nonzero
        vm.assume(blockNum1 >= 1);
        vm.assume(blockNum2 >= 1);
        // Restrict amount to exactly 10 ether for valid calls
        vm.assume(amount == 10 ether);

        // First call: set timestamp and block
        vm.warp(timestamp1);
        vm.roll(blockNum1);

        // Make first fallback call with 10 ether
        (bool success1, ) = address(c).call{value: amount}("");

        // Save balance after first call
        uint256 balanceAfterFirst = address(c).balance;

        // Second call: new timestamp and block
        vm.warp(timestamp2);
        vm.roll(blockNum2);

        // Make second fallback call with 10 ether
        (bool success2, ) = address(c).call{value: amount}("");

        // Now check the invariant: if both calls succeeded and timestamp2 > pastBlockTime (which equals timestamp1 after first call),
        // then balance should decrease only if blockNum2 % 15 == 0 (drain) or not at all (just the 10 ether addition)
        // Actually, the invariant: balance after second call should be balanceAfterFirst + 10 ether unless drain occurs and timestamp2 > timestamp1.
        // The bug: with >=, if timestamp2 == timestamp1, second call also succeeds and might drain; reference would revert second call.
        // So we test: success2 implies (timestamp2 > timestamp1) in reference; in bug, may be true even if timestamp2 == timestamp1.
        // The general property: if success2 and timestamp2 == timestamp1, then balance should not decrease (no drain) - but bug violates.
        // Simpler: property: (success1 && success2 && timestamp2 == timestamp1) => address(c).balance >= balanceAfterFirst + amount
        // In reference, success2 is false when timestamp2 == timestamp1, so implication holds vacuously. In bug, success2 is true and drain can happen decreasing balance, violating the implication.

        assertTrue(!(success1 && success2 && timestamp2 == timestamp1) || address(c).balance >= balanceAfterFirst + amount);
    }
}

