        (bool success, ) = address(c).call{value: 10 ether}("");

        // Rule: if call succeeded, contract balance is 0 (transferred) or 10 ether (kept)
        if (success) {
            uint256 balance = address(c).balance;
            if (blockNumber % 15 == 0) {
                assertTrue(balance == 0, "Balance should be 0 when block.number % 15 == 0");
            } else {
                assertTrue(balance == 10 ether, "Balance should be 10 ether when block.number % 15 != 0");
            }
        } else {
            // If reverted, balance unchanged
            assertTrue(address(c).balance == 10 ether, "Balance should remain 10 ether on revert");
        }
    }
}

